from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the "Dictionary" webpage is loaded')
def step_given_dictionary_webpage_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow time for the page to load

@given('the search input field with data-testid "search-input" is empty')
def step_given_search_input_field_is_empty(context):
    search_input = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='search-input']")
    search_input.clear()
    time.sleep(1)  # Allow time for the action to complete

@when('the user clicks the "Search" button with data-testid "search-button"')
def step_when_user_clicks_search_button(context):
    search_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='search-button']"))
    )
    search_button.click()
    time.sleep(1)  # Allow time for the action to complete

@then('the error toast with data-testid "error-toast" should be visible')
def step_then_error_toast_should_be_visible(context):
    error_toast = WebDriverWait(context.driver, 10).until(
        EC.visibility_of_element_located((By.CSS_SELECTOR, "[data-testid='error-toast']"))
    )
    assert error_toast.is_displayed(), "Error toast is not visible"

@then('the toast message should be "ERROR: Please type the word to be searched..."')
def step_then_toast_message_should_be_correct(context):
    error_toast = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='error-toast']")
    toast_message = error_toast.find_element(By.CLASS_NAME, "toast-body").text
    expected_message = "ERROR: Please type the word to be searched..."
    assert expected_message in toast_message, f"Expected '{expected_message}' but got '{toast_message}'"

def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the "Dictionary" webpage is loaded')
def step_given_dictionary_webpage_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow page to load

@given('the search input field with data-testid "search-input" contains the word "example"')
def step_given_search_input_contains_word(context):
    search_input = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='search-input']"))
    )
    search_input.clear()
    search_input.send_keys("example")
    time.sleep(1)  # Allow input to be processed

@when('the user clicks the "Search" button with data-testid "search-button"')
def step_when_user_clicks_search_button(context):
    search_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='search-button']"))
    )
    search_button.click()
    time.sleep(1)  # Allow action to be processed

@then('the error toast with data-testid "error-toast" should not be visible')
def step_then_error_toast_should_not_be_visible(context):
    error_toast = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='error-toast']")
    assert not error_toast.is_displayed(), "Error toast is visible when it should not be."

def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_visible(element):
    return element.is_displayed()

@given('the user is on the Dictionary page')
def step_given_user_on_dictionary_page(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the search input field with data-testid \'search-input\' is visible')
def step_given_search_input_visible(context):
    search_input = WebDriverWait(context.driver, 10).until(
        EC.visibility_of_element_located((By.CSS_SELECTOR, "[data-testid='search-input']"))
    )
    assert is_visible(search_input), "Search input field is not visible"

@when('the user enters \'example\' into the search input field with data-testid \'search-input\'')
def step_when_user_enters_example(context):
    search_input = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='search-input']")
    search_input.clear()
    search_input.send_keys("example")
    time.sleep(1)

@when('the user clicks the \'Search\' button with data-testid \'search-button\'')
def step_when_user_clicks_search_button(context):
    search_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='search-button']"))
    )
    search_button.click()
    time.sleep(1)

@then('the result card with data-testid \'result-card\' should be visible')
def step_then_result_card_visible(context):
    result_card = WebDriverWait(context.driver, 10).until(
        EC.visibility_of_element_located((By.CSS_SELECTOR, "[data-testid='result-card']"))
    )
    assert is_visible(result_card), "Result card is not visible"

@then('the card title with data-testid \'card-title\' should display \'example\'')
def step_then_card_title_displays_example(context):
    card_title = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='card-title']")
    expected_text = "example"
    assert expected_text.lower() in card_title.text.lower(), f"Expected '{expected_text}' in '{card_title.text}'"

@then('the word pronunciation with data-testid \'word-pronunciation\' should display the pronunciation text')
def step_then_word_pronunciation_displays(context):
    word_pronunciation = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='word-pronunciation']")
    assert word_pronunciation.text.strip(), "Word pronunciation text is not displayed"

@then('the word meaning with data-testid \'word-meaning\' should display the definition')
def step_then_word_meaning_displays(context):
    word_meaning = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='word-meaning']")
    assert word_meaning.text.strip(), "Word meaning text is not displayed"

@then('the word example with data-testid \'word-example\' should display an example sentence')
def step_then_word_example_displays(context):
    word_example = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='word-example']")
    assert word_example.text.strip(), "Word example text is not displayed"

def after_scenario(context, scenario):
    context.driver.quit()

